"""Контекст разговора: уточнения вместо новых вопросов.

Колонка слышит «буди в семь», а потом «а в выходные?» Ответ «а что?» -
бесполезен, и почти любая умная колонка на этом и ломается: она не помнит,
о чём был разговор, и уточнение уходит в языковую модель, которая уверенно
отвечает не про то.

Здесь контекст узкий и честный. Мы не строим пересказ всей беседы - мы
помним последнюю тему и подставляем её в уточнение, получая готовую фразу,
которую дальше разбирает обычный код. Никакого нового пути исполнения: если
уточнение не понято, оно уходит дальше как есть, и колонка не выдумывает.

Что помним:
- будильник: время и повтор, чтобы «а в выходные?» значило то же время;
- погоду: чтобы «а подробнее?» и «а прогноз?» относились к ней;
- таймер: чтобы «а останови» относилось к нему.

Ограничения, которые стоит знать:
- помним одну последнюю тему, а не историю;
- тема живёт несколько минут: «а подробнее?» через полчаса уже не про то;
- непонятое уточнение не превращается в выдумку - оно уходит как есть.

Проверки внизу файла: python3 vendor/irene-va/jane_context.py
"""

import re
import time

# Сколько помним последнюю тему. Долго держать нельзя: «а подробнее?»
# через два часа - это уже другой разговор, и подставлять погоду было бы
# враньём.
TTL = 600

# Темы, которые вообще можно уточнить.
TOPIC_ALARM = "alarm"
TOPIC_WEATHER = "weather"
TOPIC_TIMER = "timer"
TOPIC_HOME = "home"

# Начала уточнений. «а», «и», «ну» - признак продолжения разговора, а не
# нового вопроса. Без них «а в четверг?» не отличить от новой фразы.
# «на час позже» тоже продолжение, хотя «а» нет: так и говорят, с рук.
# Важно: «час» здесь опционален после числительного, иначе «на час позже»
# съедает «час» числительным и тут же требует второй - и не подходит.
_CONTINUE = re.compile(
    r"^(?:а|и|ну|ок|окей|а еще)\s+|"
    r"^на\s+(?:\S+\s+)?(?:час\w*|полчаса|полчасик|полчасика)\s+"
    r"(?:позже|раньше)")
_NOISE = re.compile(r"[,.!?;:]+")

# Ключи, по которым понимаем, какая тема началась. Порядок важен: погода
# стоит раньше дома, иначе «температура в гостиной» уехала бы к свету.
_TOPIC_MARKERS = (
    (TOPIC_ALARM, ("будильник", "буди меня", "разбуди", "звонок", "ал")),
    (TOPIC_WEATHER, ("погод", "градус", "температур", "дождь", "снег")),
    (TOPIC_TIMER, ("таймер", "отсчитай", "отсчёт", "отсчет")),
    (TOPIC_HOME, ("свет", "лампа", "люстра", "чайник", "телевизор",
                  "комнат", "гостиной", "кухн", "спальн", "прибор")),
)


def _norm(text):
    return " ".join(str(text or "").lower().replace("ё", "е").split())


def topic_of(phrase):
    """Какая тема началась во фразе, либо None."""
    p = _norm(phrase)
    for topic, marks in _TOPIC_MARKERS:
        for m in marks:
            if m in p:
                return topic
    return None


def is_continuation(phrase):
    """Похоже ли это на уточнение предыдущей темы."""
    p = _NOISE.sub(" ", _norm(phrase)).strip()
    return bool(_CONTINUE.match(p))


class Context(object):
    """Что помним о последнем разговоре.

    Один объект на колонку. Хранит тему, слоты и время, когда тема была
    названа. Ничего не знает про плагины и про сеть - только переписывает
    фразу, которую потом разберут они.
    """

    def __init__(self, now=None):
        self._now = now
        self.topic = None
        self.slots = {}
        self.at = 0.0
        self.turns = 0

    def _clock(self):
        # now может быть и числом, и функцией часов: тесту нужно двигать
        # время вперёд, не подменяя time.time в модуле.
        n = self._now
        if n is None:
            return time.time()
        return n() if callable(n) else n

    def _fresh(self):
        if not self.topic:
            return False
        return (self._clock() - self.at) <= TTL

    def remember(self, topic, **slots):
        """Запомнить тему и её слоты. Новая тема заменяет старую."""
        if not topic:
            return
        self.topic = topic
        self.slots = dict(slots)
        self.at = self._clock()
        self.turns += 1

    def forget(self):
        self.topic = None
        self.slots = {}
        self.at = 0.0

    def current(self):
        if not self._fresh():
            # Протухло: молча забываем, чтобы не подставлять старое.
            self.forget()
            return None, {}
        return self.topic, dict(self.slots)

    # --- уточнения по темам ------------------------------------------------

    def _alarm(self, q):
        """«а в выходные?» после «буди в семь» -> тот же час, другой повтор."""
        # «на час позже» - самостоятельное уточнение, работает и без «а».
        # Числительное опционально: «на час позже» и «на 2 часа позже».
        m = re.search(r"\bна\s+(?:\S+\s+)?(?:час\w*|полчаса|полчасик)\s+"
                      r"(позже|раньше)\b", q)
        if m and self.slots.get("hour") is not None:
            cur = int(self.slots["hour"])
            step = 1 if m.group(1) == "позже" else -1
            h = cur + step
            rep = self.slots.get("repeat_text")
            tail = (" " + rep) if rep else ""
            if h >= 24:
                # 23 ночи плюс час - это полночь следующих суток, а не
                # «ничего не изменилось»: зажимать в 23 значило бы соврать
                # колонке, что будильник остался там же.
                return "поставь будильник завтра в полночь"
            if h < 0:
                # Раньше полуночи некуда: лучше не ответить, чем поставить
                # не то время.
                return None
            if h == 0:
                return "поставь будильник в полночь"
            if h == 12:
                return "поставь будильник в полдень"
            return "поставь будильник на %d утра%s" % (h, tail)
        label = self.slots.get("label")
        if not label:
            return None
        for rx, rep in ((r"\bвыходн\w*", "по выходным"),
                        (r"\bпо\s+будням\b|\bв\s+будни\b", "по будням"),
                        (r"\bкаждый\s+день\b|\bежедневно\b", "каждый день")):
            if re.search(rx, q):
                return "поставь будильник на %s %s" % (label, rep)
        # «в четверг», «в субботу» - конкретный день
        m = re.search(r"\bв\s+(понедельник|вторник|сре[дц]у?|четверг|"
                      r"пятниц[ау]?|суббот[ау]?|воскресень[ея])\b", q)
        if m:
            return "поставь будильник на %s в %s" % (label, m.group(1))
        return None

    def _weather(self, q):
        """У погоды плагин понимает только уточнение вида, а не город."""
        if re.search(r"подробн|полный|детальн", q):
            return "погода подробно"
        if re.search(r"прогноз|завтра|неделю|на неделю", q):
            return "прогноз погоды"
        if re.search(r"сейчас|сейчас\s+же", q):
            return "какая сейчас погода"
        return None

    def _timer(self, q):
        if re.search(r"отмен|стоп|останов|хватит|выключи\s+таймер", q):
            return "отмени таймер"
        return None

    def resolve(self, phrase):
        """Переписать уточнение в готовую фразу, либо None.

        None означает «уточнение не понято, отдать как есть». Это важно:
        колонка не должна додумывать, о чём речь, если непонятно.
        """
        p = _NOISE.sub(" ", _norm(phrase)).strip()
        if not is_continuation(p):
            return None
        topic, slots = self.current()
        if not topic:
            return None
        if topic == TOPIC_ALARM:
            return self._alarm(p)
        if topic == TOPIC_WEATHER:
            return self._weather(p)
        if topic == TOPIC_TIMER:
            return self._timer(p)
        return None


# ---------------------------------------------------------------------------
# Проверки
# ---------------------------------------------------------------------------
def selfcheck():
    fails = []

    def want(cond, msg):
        if not cond:
            fails.append(msg)

    clock = [1000.0]
    c = Context(now=lambda: clock[0])

    # Пустой контекст ничего не подставляет.
    want(c.resolve("а в выходные?") is None,
         "без темы уточнение не должно превращаться в команду")

    # Будильник в семь, уточнение про выходные.
    c.remember(TOPIC_ALARM, label="7 утра", hour=7, repeat_text="")
    got = c.resolve("а в выходные?")
    want(got == "поставь будильник на 7 утра по выходным",
         "«а в выходные?» дало %r" % got)

    # Конкретный день недели.
    got = c.resolve("а в четверг?")
    want(got == "поставь будильник на 7 утра в четверг",
         "«а в четверг?» дало %r" % got)

    # Час позже - тоже уточнение по той же теме.
    got = c.resolve("на час позже")
    want(got and "8 утра" in got, "«на час позже» дало %r" % got)

    # Не тот час, который был назван: «на час позже» от девяти вечера.
    c.remember(TOPIC_ALARM, label="9 вечера", hour=21, repeat_text="")
    got = c.resolve("на час позже")
    want(got and ("22" in got or "10 вечера" in got),
         "час позже от вечернего сдвинулся неверно: %r" % got)

    # Сдвиг не выходит за сутки.
    c.remember(TOPIC_ALARM, label="23 ночи", hour=23, repeat_text="")
    got = c.resolve("на час позже")
    want(got and "полночь" in got,
         "час позже от 23 ночи должен стать полуночью, а не %r" % got)
    # Раньше полуночи некуда - честнее не ответить, чем соврать про время.
    c.remember(TOPIC_ALARM, label="полночь", hour=0, repeat_text="")
    want(c.resolve("на час раньше") is None,
         "раньше полуночи не должно выдумывать время")

    # Погода: уточнение про подробности.
    c.remember(TOPIC_WEATHER)
    want(c.resolve("а подробнее?") == "погода подробно",
         "«а подробнее?» для погоды дало %r" % c.resolve("а подробнее?"))
    want(c.resolve("а прогноз?") == "прогноз погоды",
         "«а прогноз?» для погоды дало %r" % c.resolve("а прогноз?"))

    # Таймер: остановка.
    c.remember(TOPIC_TIMER)
    want(c.resolve("а останови") == "отмени таймер",
         "«а останови» для таймера дало %r" % c.resolve("а останови"))

    # Новая тема заменяет старую: уточнение погоды не должно превратить
    # будильник в прогноз.
    c.remember(TOPIC_ALARM, label="7 утра", hour=7, repeat_text="")
    c.remember(TOPIC_WEATHER)
    want(c.resolve("а подробнее?") == "погода подробно",
         "новая тема должна заменять старую, а не смешиваться с ней")

    # Новое слово без «а» - это новый вопрос, а не уточнение.
    c.remember(TOPIC_WEATHER)
    want(c.resolve("подробнее") is None,
         "фраза без признака продолжения не должна считаться уточнением")

    # Старое уточнение забывается. Иначе «а подробнее?» через полчаса
    # означало бы погоду, о которой говорили вчера.
    c.remember(TOPIC_WEATHER)
    clock[0] += TTL + 1
    want(c.resolve("а подробнее?") is None,
         "уточнение не должно работать после истечения срока")
    want(c.current()[0] is None, "протухшая тема должна забываться")

    # А вот свежая тема после паузы работает.
    c.remember(TOPIC_ALARM, label="6 утра", hour=6, repeat_text="")
    want(c.resolve("а в выходные?") == "поставь будильник на 6 утра по выходным",
         "после паузы свежая тема должна работать")

    for f in fails:
        print("FAIL  " + f)
    if not fails:
        print("ok    jane_context: уточнение продолжает разговор, "
              "а не начинает новый")
    print("ИТОГ: провалено %d" % len(fails))
    return 1 if fails else 0


if __name__ == "__main__":
    import sys
    sys.exit(selfcheck())
